from h import *
def L(name, vals, **kw):
    r = run(vals, show=False, **kw)
    d = {k: v for k, v in r["diagnosis"].items() if v not in ("not_applicable",)}
    fired = {k: (r["urgency"].get(k) or v) for k, v in r["fired"].items()}
    extra = {k: r[k] for k in ("caveats","blocked_criteria","withheld","classification","complications","stages","risk","gaps","cautions","dark","bands") if r[k]}
    print(f"## {name}\n   dx={d}\n   fired={fired}\n   {extra}")
    return r
